function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value in nums is a whole number from 1 to 100000.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is a whole number from 1 to 100000.';
  return null;
}

