function countPairs(nums, k) {
  function gcd(a, b) {
    while (b !== 0) {
      const rest = a % b;
      a = b;
      b = rest;
    }
    return a;
  }

  const seen = new Map();
  let pairs = 0;
  for (const num of nums) {
    const g = gcd(num, k);
    for (const [other, count] of seen) {
      if ((g * other) % k === 0) {
        pairs += count;
      }
    }
    seen.set(g, (seen.get(g) || 0) + 1);
  }
  return pairs;
}

