function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  if (size === 'large') {
    const n = 2000;
    const k = pick([55440, 83160, 99991, 65536, 100000, 1 + Math.floor(rand() * 100000)]);
    const divisors = [];
    for (let d = 1; d <= k; d++) if (k % d === 0) divisors.push(d);
    const nums = Array.from({ length: n }, () => {
      if (rand() < 0.5) return 1 + Math.floor(rand() * 100000);
      const d = pick(divisors);
      const times = 1 + Math.floor(rand() * Math.floor(100000 / d));
      return d * times;
    });
    return [nums, k];
  }
  const n = 1 + Math.floor(rand() * 10);
  const k = pick([1, 2, 4, 6, 12, 8, 9, 30, 7, 1 + Math.floor(rand() * 40)]);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * 40));
  return [nums, k];
}
